import json, html, pathlib
from urllib.parse import urlparse
P=pathlib.Path(__file__).parent
projects=json.loads((P/'projects.json').read_text())
esc=lambda s:html.escape(str(s),quote=True)
icons={
 'remind':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 20h4"/></svg>',
 'stech':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8V6a2 2 0 0 1 2-2l13-1v3M16 11h5v5h-5a2.5 2.5 0 0 1 0-5Z"/></svg>',
 'learn':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 9h6v6H9zM9 2v4M12 2v4M15 2v4M9 18v4M12 18v4M15 18v4M2 9h4M2 12h4M2 15h4M18 9h4M18 12h4M18 15h4"/></svg>',
 'craft':''}
external=lambda url,label,cls='':f'<a class="{cls}" href="{esc(url)}" target="_blank" rel="noopener noreferrer">{label} <span aria-hidden="true">↗</span></a>'
def project_icon(p):
 return '<img class="project-logo" src="/assets/scraft-logo.png" alt="">' if p['id']=='craft' else icons[p['id']]
